	if len(res.Landmarks) != 2 ||
		res.Landmarks[0] != (InvalidatedLandmark{ID: "L", Occurrence: 1}) ||
		res.Landmarks[1] != (InvalidatedLandmark{ID: "M", Occurrence: 1}) {
		t.Fatalf("invalidate result = %+v", res.Landmarks)
	}

