	if lms, _ := m.LandmarksInRect(allRect()); len(lms) != 0 {
		t.Fatalf("invalidated landmarks still queried: %v", lms)
	}
	cur, _ := m.CurrentPose()
	if cur.Time != 200 {
		t.Fatalf("pose changed: %+v", cur)
	}

	h, err := m.LandmarkAppearances("L")
	if err != nil {
		t.Fatal(err)
	}
	if h.ID != "L" || len(h.Appearances) != 1 {
		t.Fatalf("history = %+v", h)
